window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[106]={"id":"106","numero":106,"titre":"Item 106 — Maladie de Parkinson","objectifs":[{"id":"106-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les symptômes qui peuvent inaugurer une maladie de Parkinson","contenu":"<div class=\"notion-course\"><p>La <span>maladie de Parkinson</span> peut être inaugurée par des <span>prodromes non moteurs</span> précédant les signes cardinaux de <span><span class=\"nc-pink nc-bold\">plusieurs années</span></span>, ou par des <span>signes révélateurs trompeurs</span> mimant une autre pathologie en l'absence de tremblement de repos.</p>\n\n<table>\n  <thead>\n    <tr><th>Mode de révélation</th><th>Manifestations</th></tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>Prodromes non moteurs</strong> <em>(<span class=\"nc-pink nc-bold\">plusieurs années</span> avant les <span class=\"nc-blue_bg\">signes moteurs</span>)</em></td>\n      <li>Olfaction : hyposmie ou diminution de l’odorat ; signe non spécifique.</li>\n    </tr>\n    <tr>\n      <td><strong>Signes révélateurs trompeurs</strong> <em>(syndrome akinéto-rigide sans <span>tremblement</span>)</em></td>\n      <td>\n        <strong>Rhumatologique :</strong> <span><span class=\"nc-orange_bg\">raideur d'un membre</span></span>, <span><span class=\"nc-orange_bg\">périarthrite scapulo-humérale</span></span> (fréquente dans Parkinson) ;<br>\n        <strong>Neuropsychique :</strong> <span>ralentissement psychomoteur</span> évoquant une <span><span class=\"nc-red_bg\">dépression</span></span>.\n      </td>\n    </tr>\n  </tbody>\n</table>\n<p class=\"obj-renvois\"><em>📎 Items liés : 107 — Mouvements anormaux</em></p><p><span class=\"nc-brown_bg\">Constipation</span>, hyposmie, <span class=\"nc-red_bg\">dépression</span> et trouble du comportement en <span class=\"nc-green_bg\">sommeil</span> paradoxal peuvent précéder les <span class=\"nc-blue_bg\">signes moteurs</span>, mais aucun ne suffit isolément au diagnostic. Une maladie de Parkinson peut rester sans tremblement.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418141a8b8f9a534437b3f?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Maladie de Parkinson (106)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-17-item-106-maladie-de-parkinson\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 106, chapitre actuel</a></li></ul><p></p></details><details><summary>Situations de départ LiSA vérifiées</summary><ul><li><a href=\"https://livret.uness.fr/lisa/2026/Tremblements_SDD-128\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 128 · Tremblements</a><ul><li>Distinguer types de tremblement et signes de parkinsonisme typique/atypique.</li><li>Rechercher iatrogénie, proposer traitement et suivi des complications.</li></ul></li><li><a href=\"https://livret.uness.fr/lisa/2026/Mouvements_anormaux_SDD-126\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 126 · Mouvements anormaux</a><ul><li>Décrire le mouvement et son impact, rechercher iatrogénie et syndromes associés.</li><li>Orienter bilan, traitement et rééducation.</li></ul></li></ul><p>Attendus consultés directement sur LiSA 2026 le 13 octobre 2026. Les arbres ATLAS sont des synthèses pédagogiques reliées aux cours complets.</p></details>","frequence":3},{"id":"106-2","rang":"A","rubrique":"Diagnostic positif","titre":"Décrire les signes cliniques d’une maladie de Parkinson","contenu":"<div class=\"notion-course\"><p>Le <span>syndrome parkinsonien</span> = <strong><span class=\"nc-yellow_bg\">bradykinésie</span> + [rigidité plastique et/ou tremblement de repos]</strong>. Une caractéristique cardinale : <strong>début <span><span class=\"nc-red nc-bold\">unilatéral</span></span> ou <span><span class=\"nc-red nc-bold\">asymétrique</span></span></strong>, l'<span><span class=\"nc-red nc-bold\">asymétrie</span></span> persistant tout au long de la maladie.</p>\n\n<table>\n  <thead>\n    <tr><th>Signe cardinal</th><th>Définition</th><th>Manifestations cliniques</th></tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong><span class=\"nc-yellow_bg\">Bradykinésie</span></strong></td>\n      <td>Mouvements plus <span>lents</span> (ralentissement à l'exécution, décrément de la vitesse). Associée parfois à : <strong><span class=\"nc-yellow_bg\">Hypokinésie</span></strong> (mouvements moins amples), <strong><span class=\"nc-yellow_bg\">Akinésie</span></strong> (défaut d'initiation).</td>\n      <td>\n        <strong>Écriture :</strong> <span><span class=\"nc-blue_bg\">micrographie</span></span> (<span>réduction</span> de la taille des lettres) ;<br>\n        <strong>Phonation :</strong> <span><span class=\"nc-blue_bg\">voix monocorde et monotone</span></span> ;<br>\n        <strong>Marche :</strong> <span><span class=\"nc-blue_bg\">lenteur</span>, <span class=\"nc-blue_bg\">marche à petits pas</span>, <span class=\"nc-blue_bg\">perte du ballant du bras</span></span> ;<br>\n        <strong>Face :</strong> <span><span class=\"nc-blue_bg\">hypomimie</span></span>, <span class=\"nc-blue_bg\">pauvreté des mouvements spontanés</span> (clignement des yeux) ;<br>\n        <strong><span class=\"nc-blue nc-bold\">Membres</span> :</strong> <span class=\"nc-blue_bg\">ralentissement des gestes alternatifs rapides</span> — <span><span class=\"nc-red nc-bold\">opposition pouce-index</span></span>, <span><span class=\"nc-red nc-bold\">battre à mesure avec le pied</span></span> <em>(et non doigt-nez, qui explore le <span><span class=\"nc-red_bg\">syndrome cérébelleux</span></span>)</em>.\n      </td>\n    </tr>\n    <tr>\n      <td><strong>Rigidité plastique « en tuyau de plomb »</strong></td>\n      <td>Rigidité <span>plastique</span> (ne revient pas à sa forme initiale), à différencier de la rigidité spastique.</td>\n      <td>\n        <strong>Topographie :</strong> <span><span class=\"nc-blue_bg\">extrémités</span></span> et <span><span class=\"nc-blue_bg\">nuque</span></span> ;<br>\n        <strong>Mobilisation passive :</strong> résistance constante qui <span class=\"nc-blue_bg\">cède par à-coups en </span><span><span class=\"nc-blue_bg\">« roue dentée »</span></span> ;<br>\n        <strong>Sensibilisation :</strong> <span>manœuvre de Froment</span> — mouvements passifs d'une main + tâche volontaire avec l'autre main = rigidité majorée du côté passif.\n      </td>\n    </tr>\n    <tr>\n      <td><strong>Tremblement de repos</strong></td>\n      <td>Tremblement <span><span class=\"nc-pink nc-bold\">lent</span></span>, <span><span class=\"nc-red nc-bold\">asymétrique</span></span>, disparaissant au <span class=\"nc-green_bg\">mouvement</span> et au <span class=\"nc-green_bg\">sommeil</span>.</td>\n      <td>\n        <strong>Fréquence :</strong> <span>4-6 Hz</span> ;<br>\n        <strong>Latéralité :</strong> <span><span class=\"nc-red nc-bold\">unilatéral</span></span> ou <span><span class=\"nc-red nc-bold\">asymétrique</span></span> ;<br>\n        <strong>Topographie :</strong> <span class=\"nc-blue_bg\">membres en distalité</span>, <span class=\"nc-blue_bg\">lèvres</span>, <span class=\"nc-blue_bg\">menton</span>, <span class=\"nc-blue_bg\">langue</span> — <strong>ne touche <span class=\"nc-red_bg\">pas le chef</span> <span class=\"nc-red_bg\">(la tête)</span></strong> ;<br>\n        <strong>Facteurs aggravants :</strong> <span><span class=\"nc-red nc-bold\">émotion</span></span>, <span><span class=\"nc-red nc-bold\">calcul mental</span></span> ;<br>\n        <strong>Facteurs calmants :</strong> disparaît lors du <span><span class=\"nc-green_bg\">mouvement</span> volontaire</span> et du <span><span class=\"nc-green_bg\">sommeil</span></span>.\n      </td>\n    </tr>\n  </tbody>\n</table>\n<p class=\"obj-renvois\"><em>📎 Items liés : 107 — Mouvements anormaux · 91 — Déficit neuro récent</em></p><div class=\"callout\"><p><span class=\"nc-yellow_bg\">Bradykinésie</span> = <span class=\"nc-blue_bg\">lenteur</span> avec décrément d’amplitude ou de vitesse lors des mouvements répétés. Le tremblement peut manquer. La rigidité est une résistance à la mobilisation passive, peu dépendante de la vitesse, contrairement à la spasticité.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418141a8b8f9a534437b3f?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Maladie de Parkinson (106)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-17-item-106-maladie-de-parkinson\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 106, chapitre actuel</a></li></ul><p></p></details>","frequence":6},{"id":"106-3","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître le processus physiopathologique de la maladie de Parkinson","contenu":"<div class=\"notion-course\"><h4>Circuit nigro-striatal</h4><ul><li>Striatum = noyau caudé + putamen. Noyau lenticulaire = putamen + pallidum ; ne pas y inclure le noyau caudé.</li><li>Dégénérescence <span class=\"nc-red nc-bold\">progressive</span> des <span class=\"nc-yellow_bg nc-bold\">neurones dopaminergiques</span> <span class=\"nc-yellow_bg\">de la</span> substance noire pars compacta, qui projettent vers le striatum ; dysfonctionnement des circuits de sélection et d’automatisation du <span class=\"nc-green_bg\">mouvement</span>.</li><li><span class=\"nc-yellow_bg nc-bold\">Corps de Lewy</span> : inclusions neuronales contenant notamment de l’<span class=\"nc-pink nc-bold\">alpha-synucléine</span> anormalement agrégée.</li><li>L’atteinte dépasse les seuls circuits dopaminergiques : troubles autonomes, du <span class=\"nc-green_bg\">sommeil</span>, cognitifs et signes axiaux expliquent les limites du <span class=\"nc-pink_bg nc-bold\">traitement dopaminergique</span>.</li></ul><h4>Terrain et causes</h4><p>Maladie multifactorielle : <span class=\"nc-red nc-bold\">âge</span>, susceptibilité génétique et expositions environnementales, notamment certains <span class=\"nc-red nc-bold\">pesticides</span>. Les formes monogéniques sont minoritaires, davantage évoquées en cas de début jeune ou d’histoire familiale. Une exposition professionnelle justifie une évaluation adaptée.</p><div class=\"callout\"><p>La perte neuronale est importante avant la révélation motrice, mais il n’existe pas de pourcentage individuel mesurable au lit du patient permettant de dater la maladie. La lévodopa traite les symptômes ; elle ne restaure pas les neurones perdus.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418141a8b8f9a534437b3f?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Maladie de Parkinson (106)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-17-item-106-maladie-de-parkinson\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 106, chapitre actuel</a></li></ul><p></p></details>","frequence":3,"liens":[{"href":"https://radiopaedia.org/articles/basal-ganglia","label":"Radiopaedia : Basal ganglia (anatomie)"}]},{"id":"106-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques dont l’association à un syndrome parkinsonien va à l’encontre du diagnostic de maladie de Parkinson","contenu":"<div class=\"notion-course\"><p>Une maladie de Parkinson typique associe syndrome parkinsonien, début souvent <span class=\"nc-red nc-bold\">asymétrique</span>, progression graduelle et réponse nette et durable à la dopathérapie. Rechercher des signes atypiques, surtout précoces ou disproportionnés.</p><table><thead><tr><th>Alerte</th><th>Orientation</th></tr></thead><tbody><tr><td><span class=\"nc-red nc-bold\">Chutes précoces</span>, ralentissement des saccades/paralysie supranucléaire verticale, atteinte axiale</td><td><span class=\"nc-orange_bg\">Paralysie supranucléaire progressive</span> (PSP).</td></tr><tr><td><span class=\"nc-orange nc-bold\">Dysautonomie</span> sévère <span class=\"nc-red nc-bold\">précoce</span> : <span class=\"nc-blue_bg\">hypotension orthostatique</span>, rétention/incontinence ; <span class=\"nc-red_bg\">syndrome cérébelleux</span></td><td><span class=\"nc-orange_bg\">Atrophie multisystématisée</span> (AMS).</td></tr><tr><td><span class=\"nc-red_bg\">Apraxie</span> <span class=\"nc-red nc-bold\">asymétrique</span>, déficit sensitif cortical, main étrangère, <span class=\"nc-red_bg\">myoclonies</span></td><td>Syndrome corticobasal.</td></tr><tr><td>Déclin cognitif <span class=\"nc-red nc-bold\">précoce</span>, fluctuations, hallucinations visuelles, trouble du <span class=\"nc-green_bg\">sommeil</span> paradoxal</td><td>Maladie à <span class=\"nc-yellow_bg nc-bold\">corps de Lewy</span>.</td></tr><tr><td>Déficit pyramidal, progression rapide, signes bulbaires précoces, faible réponse à un essai adéquat</td><td>Rechercher syndrome atypique, lésionnel, vasculaire ou iatrogène.</td></tr></tbody></table><h4>Examens raisonnés</h4><ul><li>Présentation typique : diagnostic clinique, pas d’IRM ou DaTSCAN systématique.</li><li>Présentation atypique : <span class=\"nc-blue_bg\">IRM cérébrale</span> et bilan guidé par la clinique. Avant 40 ans, rechercher notamment maladie de Wilson par bilan cuprique et IRM.</li><li>DaTSCAN : aide dans certains doutes entre déficit dopaminergique <span class=\"nc-red nc-bold\">dégénératif</span> et <span class=\"nc-orange_bg\">tremblement essentiel</span>/parkinsonisme médicamenteux ; ne distingue pas à lui seul Parkinson, AMS et PSP.</li><li>Les <span class=\"nc-blue_bg\">signes non moteurs</span> et certaines anomalies tardives peuvent appartenir à Parkinson ; « examen entièrement normal hors triade » est un raccourci, à replacer dans la chronologie.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418141a8b8f9a534437b3f?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Maladie de Parkinson (106)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-17-item-106-maladie-de-parkinson\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 106, chapitre actuel</a></li></ul><p></p></details>","frequence":5,"liens":[{"href":"https://radiopaedia.org/articles/wilson-disease-2","label":"Radiopaedia : Wilson disease"}]},{"id":"106-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les manifestations de la phase des complications motrices","contenu":"<div class=\"notion-course\"><p>Les complications motrices apparaissent après une durée variable d’évolution et d’exposition au <span class=\"nc-green_bg\">traitement</span>, souvent après <span class=\"nc-pink nc-bold\">plusieurs années</span>. Le jeune âge de début, la dose de lévodopa et la durée <span class=\"nc-yellow_bg\">de la</span> maladie favorisent leur apparition.</p>\n\n\n\n<table>\n  <thead>\n    <tr><th>Complication</th><th>Manifestations</th></tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>Fluctuations d'efficacité du <span class=\"nc-green_bg\">traitement</span></strong></td>\n      <td>\n        <strong><span class=\"nc-yellow_bg\">Akinésie de fin de dose</span> :</strong> réapparition des signes parkinsoniens avant la prise suivante (durée d'action L-DOPA tombe à <span><span class=\"nc-pink nc-bold\">60-90 min</span></span> aux <span class=\"nc-red nc-bold\">stades avancés</span>, ≈ demi-vie plasmatique) ;<br>\n        <strong><span class=\"nc-yellow_bg\">Akinésie</span> de nuit / petit <span class=\"nc-pink nc-bold\">matin</span> :</strong> <span class=\"nc-blue_bg\">lenteur</span>, <span class=\"nc-blue_bg\">crampes des mollets et orteils</span>, difficultés à se tourner dans le lit ;<br>\n        <strong><span class=\"nc-yellow_bg\">Phénomène </span><span><span class=\"nc-yellow_bg\">ON/OFF</span></span> :</strong> passage brutal de l'état non-parkinsonien à l'état parkinsonien.\n      </td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"nc-blue_bg\">Dyskinésies</span></strong></td>\n      <td>\n        <strong><span class=\"nc-blue_bg\">Dyskinésies</span> de <span class=\"nc-red nc-bold\">milieu</span> / <span class=\"nc-red nc-bold\">pic</span> de dose :</strong> mouvements involontaires plutôt <span><span class=\"nc-blue_bg\">choréiques</span></span> des <span class=\"nc-blue nc-bold\">membres</span> et du <span class=\"nc-blue nc-bold\">tronc</span> ;<br>\n        <strong><span class=\"nc-blue_bg\">Dyskinésies</span> <span class=\"nc-red nc-bold\">biphasiques</span> :</strong> de début ou de fin de dose, plutôt <span>dystoniques</span> des <span class=\"nc-red nc-bold\">membres inférieurs</span>, souvent douloureuses.\n      </td>\n    </tr>\n  </tbody>\n</table>\n\n<h4>Signes dopasensibles <span>vs</span> non dopasensibles</h4>\n<table>\n  <thead>\n    <tr><th>Dopasensibles</th><th>Non dopasensibles</th></tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><span>Tremblement de repos</span></td>\n      <td><span>Troubles de l'adaptation posturale</span> (chutes — non liés à une dénervation dopaminergique pure, survenue tardive)</td>\n    </tr>\n    <tr>\n      <td><span><span class=\"nc-yellow_bg\">Bradykinésie</span></span></td>\n      <td><span>Dysarthrie</span></td>\n    </tr>\n    <tr>\n      <td><span>Hypertonie plastique</span></td>\n      <td><span><span class=\"nc-red_bg\">Troubles cognitifs</span></span></td>\n    </tr>\n  </tbody>\n</table><h4>Adapter après avoir documenté</h4><p>Noter heures des prises, repas, état ON/OFF et <span class=\"nc-blue_bg\">dyskinésies</span> dans un agenda. Wearing-off : réapparition prévisible avant la prise suivante. On-off : bascules parfois imprévisibles. <span class=\"nc-blue_bg\">Dyskinésies</span> de <span class=\"nc-red nc-bold\">pic</span> de dose : plutôt <span class=\"nc-blue_bg\">choréiques</span> ; <span class=\"nc-red nc-bold\">biphasiques</span> : début/fin de dose, souvent aux <span class=\"nc-red nc-bold\">membres inférieurs</span>. <span class=\"nc-blue_bg\">Dystonie</span> de période OFF : notamment pied douloureux au réveil.</p><p>Le neurologue peut fractionner la lévodopa, ajuster les formulations ou associer <span class=\"nc-pink_bg\">IMAO-B</span>/ICOMT/agoniste selon le terrain ; amantadine si <span class=\"nc-blue_bg\">dyskinésies</span> gênantes. Éviter d’augmenter automatiquement la dose devant tout <span class=\"nc-green_bg\">mouvement</span> anormal.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418141a8b8f9a534437b3f?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Maladie de Parkinson (106)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-17-item-106-maladie-de-parkinson\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 106, chapitre actuel</a></li></ul><p></p></details>","frequence":1},{"id":"106-6","rang":"B","rubrique":"Diagnostic positif","titre":"Enoncer les manifestations de la phase de déclin moteur","contenu":"<div class=\"notion-course\"><p>La <span>phase de déclin moteur</span> correspond à l'apparition de <span><span class=\"nc-blue_bg\">signes moteurs axiaux</span></span> <span class=\"nc-red nc-bold\">peu ou pas sensibles aux traitements dopaminergiques</span> (le processus <span class=\"nc-red nc-bold\">dégénératif</span> dépasse alors la <span class=\"nc-yellow_bg nc-bold\">voie nigro-striatale</span>).</p>\n\n<table>\n  <thead>\n    <tr><th>Domaine axial</th><th>Manifestations</th><th>Risques</th></tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong><span>Troubles bulbaires</span></strong></td>\n      <td><span><span class=\"nc-blue_bg\">Dysarthrie</span></span>, <span><span class=\"nc-blue_bg\">dysphagie</span></span>, <span><span class=\"nc-blue_bg\">hypersialorrhée</span></span> (par diminution de la déglutition spontanée).</td>\n      <td><span><span class=\"nc-red nc-bold\">Fausses routes</span></span>, <span><span class=\"nc-red nc-bold\">pneumopathies</span> d'inhalation</span>.</td>\n    </tr>\n    <tr>\n      <td><strong><span>Troubles de la marche</span></strong></td>\n      <td><span>Réduction de la longueur des enjambées</span> ; <span><span class=\"nc-blue_bg\">freezing / enrayement cinétique</span></span> (pieds collés au sol à l'initiation, au demi-tour, au passage d'un obstacle) ; <span><span class=\"nc-blue_bg\">festination</span></span> (emballement brutal de la marche).</td>\n      <td><span><span class=\"nc-red nc-bold\">Chutes vers l'avant</span></span>.</td>\n    </tr>\n    <tr>\n      <td><strong><span>Troubles de l'équilibre postural</span></strong></td>\n      <td><span><span class=\"nc-blue_bg\">Perte progressive des réflexes posturaux</span></span>.</td>\n      <td><span><span class=\"nc-red nc-bold\">Chutes vers l'arrière</span></span>.</td>\n    </tr>\n    <tr>\n      <td><strong><span>Troubles de la posture</span></strong></td>\n      <td><span><span class=\"nc-orange_bg\">Triple flexion</span></span> ; <span>camptocormie</span> (flexion du tronc vers l'avant) ; <span><span class=\"nc-orange_bg\">syndrome de Pise</span></span> (flexion latérale du tronc).</td>\n      <td>Compensation difficile, retentissement fonctionnel.</td>\n    </tr>\n  </tbody>\n</table>\n<p class=\"obj-renvois\"><em>📎 Items liés : 109 — Trouble marche - équilibre</em></p><p>Le freezing peut être dopasensible en période OFF ou moins sensible aux <span class=\"nc-red nc-bold\">stades avancés</span>. Rechercher une cause intercurrente de dégradation brutale : infection, hypotension, <span class=\"nc-blue nc-bold\">constipation</span>, oublis ou médicament antidopaminergique. Évaluer déglutition et risque de chute ; adapter les aides.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418141a8b8f9a534437b3f?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Maladie de Parkinson (106)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-17-item-106-maladie-de-parkinson\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 106, chapitre actuel</a></li></ul><p></p></details>","frequence":1},{"id":"106-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les manifestations de la phase de déclin cognitif et comportemental","contenu":"<div class=\"notion-course\"><h4>Troubles non moteurs et cognition</h4><table><thead><tr><th>Domaine</th><th>Manifestations et conduite</th></tr></thead><tbody><tr><td>Cognition</td><td>Ralentissement et <span class=\"nc-blue nc-bold\">syndrome dysexécutif</span>, puis possible trouble neurocognitif majeur avec perte d’autonomie. Dépister et suivre ; ce n’est pas une évolution uniforme à date fixe.</td></tr><tr><td><span class=\"nc-blue nc-bold\">Hallucinations</span> / délire</td><td>Liés à la maladie, à certains médicaments ou à un facteur intercurrent. Un début aigu impose de rechercher une confusion.</td></tr><tr><td>Humeur / comportement</td><td><span class=\"nc-red_bg\">Dépression</span>, <span class=\"nc-red_bg\">anxiété</span>, <span class=\"nc-red_bg\">apathie</span> ; <span class=\"nc-red_bg\">troubles du contrôle des impulsions</span> sous <span class=\"nc-pink_bg nc-bold\">traitement dopaminergique</span>. Interroger aussi l’entourage.</td></tr><tr><td>Autonomie</td><td><span class=\"nc-blue_bg\">Hypotension orthostatique</span>, <span class=\"nc-blue nc-bold\">constipation</span>, troubles urinaires ou sexuels ; <span class=\"nc-green_bg\">traitement</span> ciblé et revue médicamenteuse.</td></tr><tr><td><span class=\"nc-green_bg\">Sommeil</span> / douleur</td><td>Somnolence, attaques d’endormissement, insomnie, trouble du comportement en <span class=\"nc-green_bg\">sommeil</span> paradoxal ; <span class=\"nc-blue_bg\">douleurs</span> dystoniques, musculosquelettiques ou autres.</td></tr></tbody></table><h4>Devant des hallucinations nouvelles</h4><ol><li>Rechercher infection, déshydratation, douleur, rétention, trouble métabolique et nouvelles prescriptions.</li><li>Réviser avec le spécialiste les médicaments aggravants, notamment anticholinergiques et agonistes ; ne pas arrêter brutalement la lévodopa.</li><li>Si psychose menaçante persistante, <span class=\"nc-green_bg\">traitement</span> spécialisé compatible avec le parkinsonisme, avec surveillance spécifique ; éviter les bloqueurs dopaminergiques usuels.</li></ol><p>Un trouble cognitif précédant ou accompagnant de près le syndrome parkinsonien oriente vers la maladie à <span class=\"nc-yellow_bg nc-bold\">corps de Lewy</span> ; un déclin après une maladie de Parkinson établie depuis des années relève du trouble cognitif associé à Parkinson.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418141a8b8f9a534437b3f?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Maladie de Parkinson (106)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-17-item-106-maladie-de-parkinson\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 106, chapitre actuel</a></li></ul><p></p></details>","frequence":2},{"id":"106-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les différentes classes de médicaments antiparkinsoniens","contenu":"<div class=\"notion-course\"><table><thead><tr><th>Classe</th><th>Place</th><th>Vigilance</th></tr></thead><tbody><tr><td>Lévodopa + <span class=\"nc-pink nc-bold\">carbidopa</span> ou <span class=\"nc-pink nc-bold\">bensérazide</span></td><td>Précurseur de dopamine + inhibiteur périphérique de la décarboxylase. <span class=\"nc-green_bg\">Traitement</span> moteur le plus efficace.</td><td><span class=\"nc-red_bg\">Nausées</span>, hypotension, <span class=\"nc-red_bg\">hallucinations</span> ; fluctuations et <span class=\"nc-blue_bg\">dyskinésies</span> avec l’évolution.</td></tr><tr><td>Agonistes dopaminergiques</td><td>Pramipexole, ropinirole, rotigotine, piribédil ; apomorphine en injection/pompe spécialisée.</td><td><span class=\"nc-red_bg\">Troubles du contrôle des impulsions</span>, achats/jeux/<span class=\"nc-red nc-bold\">hypersexualité</span>, somnolence et accès de <span class=\"nc-green_bg\">sommeil</span>, <span class=\"nc-red_bg\">hallucinations</span>, œdèmes, hypotension.</td></tr><tr><td><span class=\"nc-pink_bg\">IMAO-B</span></td><td><span class=\"nc-pink nc-bold\">Rasagiline</span>, sélégiline ; safinamide dans certaines associations. Effet dopaminergique, seul ou en complément selon molécule.</td><td>Interactions et tolérance ; pas de bénéfice neuroprotecteur établi à promettre.</td></tr><tr><td>ICOMT</td><td>Entacapone ou opicapone notamment ; prolongent l’effet de la lévodopa et s’y associent.</td><td><span class=\"nc-blue_bg\">Dyskinésies</span>, diarrhée, coloration des urines selon molécule ; surveillance propre à la spécialité.</td></tr><tr><td>Amantadine</td><td><span class=\"nc-yellow_bg\">Traitement des dyskinésies</span> dans les situations adaptées.</td><td>Confusion/hallucinations, œdèmes, livedo ; adaptation à la fonction rénale.</td></tr><tr><td>Anticholinergiques</td><td>Place restreinte chez certains sujets jeunes sans atteinte <span class=\"nc-red_bg\">cognitive</span>.</td><td>Confusion, rétention urinaire, <span class=\"nc-brown_bg\">constipation</span>, glaucome ; à éviter chez le sujet âgé/cognitif.</td></tr></tbody></table><div class=\"callout\"><p>Informer patient et proche des troubles des impulsions avant un agoniste et les rechercher à chaque suivi. Une diminution doit être encadrée : le sevrage brutal peut être mal toléré. Respecter les horaires de lévodopa, notamment lors d’une hospitalisation.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418141a8b8f9a534437b3f?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Maladie de Parkinson (106)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-17-item-106-maladie-de-parkinson\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 106, chapitre actuel</a></li></ul><p></p></details>","frequence":2},{"id":"106-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les thérapeutiques non médicamenteuses et l’importance de la kinésithérapie","contenu":"<div class=\"notion-course\"><h4>Rééducation dès le début, adaptée au stade</h4><p>Activité physique régulière et kinésithérapie individualisée : endurance, force, amplitude des mouvements, équilibre, marche et transferts. Programmer les séances lorsque l’état moteur et la sécurité le permettent, souvent en période ON ; ne pas imposer le <span class=\"nc-pink nc-bold\">matin</span> <span class=\"nc-yellow_bg nc-bold\">avant</span> la première lévodopa ni rechercher systématiquement l’épuisement.</p><table><thead><tr><th>Objectif</th><th>Moyens</th></tr></thead><tbody><tr><td>Marche et freezing</td><td>Travail de longueur du pas, demi-tours larges, repères visuels/rythmiques, stratégies d’initiation ; double tâche seulement si adaptée et sûre.</td></tr><tr><td>Posture / mobilité</td><td>Étirements, renforcement des extenseurs, mobilité axiale, retournements et transferts ; prévention des complications aux <span class=\"nc-red nc-bold\">stades avancés</span>.</td></tr><tr><td>Voix et déglutition</td><td>Orthophonie, exercices adaptés de phonation ; évaluation des <span class=\"nc-red nc-bold\">fausses routes</span> et stratégies de déglutition personnalisées.</td></tr><tr><td>Autonomie</td><td>Ergothérapie, aménagement du domicile, évaluation du chaussage et des aides techniques. Canne ou déambulateur selon évaluation, sans exclusion générale du déambulateur.</td></tr><tr><td>Vie sociale</td><td>Éducation thérapeutique, ALD, aides selon handicap, associations, soutien du patient et de l’aidant.</td></tr></tbody></table><h4>Traitements spécialisés des <span class=\"nc-red nc-bold\">stades avancés</span></h4><ul><li>Stimulation cérébrale profonde du noyau subthalamique ou du pallidum : sélection multidisciplinaire, symptômes dopasensibles et complications gênantes malgré <span class=\"nc-green_bg\">traitement</span> optimisé, cognition et psychiatrie compatibles. L’âge et les comorbidités sont évalués individuellement.</li><li>Autres options selon situation : pompe d’apomorphine, administration continue de lévodopa.</li><li>Ces traitements ne guérissent pas la maladie et ne corrigent pas tous les troubles axiaux ou cognitifs dopa-résistants.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418141a8b8f9a534437b3f?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Maladie de Parkinson (106)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-17-item-106-maladie-de-parkinson\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 106, chapitre actuel</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2038173/fr/maladie-de-parkinson-et-syndromes-apparentes-techniques-et-modalites-de-la-prise-en-charge-non-medicamenteuse-des-troubles-moteurs\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Parkinson : prise en charge non médicamenteuse des troubles moteurs</a></li></ul><p>Les consignes systématiques « avant la première prise », « fatigue à chaque exercice » et « préférer toujours la canne » ont été corrigées au profit d’une rééducation individualisée.</p></details>","frequence":4},{"id":"106-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement à la phase initiale de la maladie","contenu":"<div class=\"notion-course\"><h4>Décider avec le patient</h4><p>Traiter lorsque les symptômes gênent les activités ou la qualité de vie. Choisir selon âge, retentissement, cognition, risque psychiatrique, somnolence, profession et préférences ; titration <span class=\"nc-red nc-bold\">progressive</span> et réévaluation <span class=\"nc-yellow_bg\">de la</span> tolérance.</p><table><thead><tr><th>Situation</th><th>Orientation</th></tr></thead><tbody><tr><td>Sujet âgé, fragilité <span class=\"nc-red_bg\">cognitive</span> ou <span class=\"nc-red nc-bold\">handicap moteur</span> marqué</td><td>Lévodopa généralement privilégiée pour son efficacité et sa tolérance relative.</td></tr><tr><td>Sujet plus jeune sans contre-indication</td><td>Lévodopa possible ; agoniste ou <span class=\"nc-pink_bg\">IMAO-B</span> dans certaines situations. Ne pas retarder une lévodopa nécessaire uniquement par crainte des complications futures.</td></tr><tr><td>Contrôle insuffisant</td><td>Vérifier diagnostic, prises, horaires, observance et tolérance avant augmentation ou association.</td></tr><tr><td>Nausées à l’instauration</td><td>Titration adaptée ; antiémétique seulement si indiqué. Éviter <span class=\"nc-pink_bg\">métoclopramide</span> et autres antagonistes dopaminergiques centraux.</td></tr></tbody></table><h4><span class=\"nc-pink_bg\">Dompéridone</span> : prescription prudente</h4><p>Si nécessaire et sans contre-indication, utiliser la dose efficace la plus faible et la durée la plus courte ; chez l’adulte, repère usuel 10 mg jusqu’à trois fois par jour, maximum 30 mg/j, en général au plus sept jours. Risque d’allongement du QT et d’arythmie : vérifier terrain, interactions et besoin d’ECG. La dose de 80 mg/j n’est pas un repère de prescription courante.</p><p>Associer dès le diagnostic activité physique, kinésithérapie, information et suivi non moteur. Ne jamais interrompre brutalement un <span class=\"nc-pink_bg nc-bold\">traitement dopaminergique</span>, notamment à l’occasion d’un jeûne ou d’une hospitalisation.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418141a8b8f9a534437b3f?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Maladie de Parkinson (106)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-17-item-106-maladie-de-parkinson\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 106, chapitre actuel</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2038173/fr/maladie-de-parkinson-et-syndromes-apparentes-techniques-et-modalites-de-la-prise-en-charge-non-medicamenteuse-des-troubles-moteurs\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Parkinson : prise en charge non médicamenteuse des troubles moteurs</a></li><li><a href=\"https://ansm.sante.fr/actualites/la-domperidone-motilium-et-generiques-ne-doit-plus-etre-utilisee-chez-lenfant-de-moins-de-12-ans\" target=\"_blank\" rel=\"noopener noreferrer\">ANSM · Bon usage de la dompéridone</a></li></ul><p></p></details>","frequence":3},{"id":"106-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître les médicaments susceptibles d’induire un syndrome parkinsonien","contenu":"<div class=\"notion-course\"><h4>Rechercher tous les médicaments, même hors psychiatrie</h4><table><thead><tr><th>Groupe</th><th>Exemples</th></tr></thead><tbody><tr><td>Antipsychotiques</td><td><span class=\"nc-pink_bg\">Neuroleptiques</span>, particulièrement ceux à fort antagonisme D2.</td></tr><tr><td>Médicaments à effet antidopaminergique moins visible</td><td><span class=\"nc-pink_bg\">Métoclopramide</span>, <span class=\"nc-pink_bg\">métopimazine</span> ; certaines molécules utilisées comme antihistaminiques ou anti-vertigineux.</td></tr><tr><td>Autres médicaments pouvant provoquer un parkinsonisme</td><td>Flunarizine, trimétazidine, <span class=\"nc-pink_bg\">valproate</span>, <span class=\"nc-pink_bg\">lithium</span>, notamment. Tous ne sont pas des <span class=\"nc-pink_bg\">neuroleptiques</span> et les mécanismes diffèrent.</td></tr></tbody></table><p>Début après introduction/augmentation, présentation souvent <span class=\"nc-yellow_bg\">symétrique</span> et <span class=\"nc-blue_bg\">dyskinésies</span> associées orientent, sans constituer une preuve. Une <span class=\"nc-red nc-bold\">asymétrie</span> est possible ; le <span class=\"nc-green_bg\">traitement</span> peut révéler une maladie de Parkinson sous-jacente.</p><h4>Conduite</h4><ol><li>Reconstituer la chronologie et revoir l’indication avec le prescripteur. Diminuer, arrêter ou substituer si possible, sans rupture intempestive d’un <span class=\"nc-green_bg\">traitement</span> indispensable.</li><li>Si antipsychotique nécessaire : choix spécialisé à faible risque extrapyramidal, notamment <span class=\"nc-pink_bg\">clozapine</span> ou <span class=\"nc-pink_bg\">quétiapine</span> selon indication et contexte. <span class=\"nc-pink_bg\">Clozapine</span> : surveillance hématologique et autres précautions selon RCP actualisé.</li><li>Éviter une prescription systématique d’anticholinergique correcteur, particulièrement chez le sujet âgé ou confus.</li><li>Réévaluer après adaptation ; récupération parfois lente ou incomplète. Si persistance/doute : avis neurologique, éventuellement DaTSCAN ciblé.</li></ol></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418141a8b8f9a534437b3f?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Maladie de Parkinson (106)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-17-item-106-maladie-de-parkinson\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 106, chapitre actuel</a></li></ul><p></p></details>","frequence":2},{"id":"106-12","rang":"A","rubrique":"Contenu multimédia","titre":"Chez un patient réel ou sur un cas vidéo, définir les éléments qui orientent vers le diagnostic de maladie de Parkinson","contenu":"<div class=\"notion-course\"><h4>Grille d’observation au lit du patient ou en vidéo</h4><ol><li>Observer au repos : <span class=\"nc-blue_bg\">hypomimie</span>, raréfaction du clignement, tremblement distal ; noter côté et contexte.</li><li>Demander des mouvements répétés : <span class=\"nc-red nc-bold\">opposition pouce-index</span>, ouverture-fermeture des mains, pronosupination, frappes du pied ; chercher <span class=\"nc-blue_bg\">lenteur</span> ET décrément.</li><li>Examiner la rigidité par mobilisation passive, éventuellement avec manœuvre de Froment. Une vidéo seule ne permet pas de palper le tonus.</li><li>Observer lever, marche, ballant des bras, longueur du pas, demi-tour et freezing ; sécuriser l’épreuve.</li><li>Tester écriture, voix, oculomotricité, signes pyramidaux/<span class=\"nc-purple nc-bold\">cérébelleux</span> et cognition ; rechercher les drapeaux rouges et médicaments.</li></ol><div class=\"callout\"><p>La triade complète n’est pas obligatoire : <span class=\"nc-yellow_bg\">bradykinésie</span> avec rigidité et/ou tremblement de repos. <span class=\"nc-red nc-bold\">Asymétrie</span> et réponse dopaminergique soutiennent le diagnostic ; un tremblement isolé ne suffit pas.</p></div><p>Pour s’entraîner : <a href=\"https://www.cen-neurologie.fr/videotheque\" target=\"_blank\" rel=\"noopener noreferrer\">vidéothèque du CEN</a>. Distinguer ce qui est visible, ce qui exige un examen direct et ce qui dépend de l’interrogatoire.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418141a8b8f9a534437b3f?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Maladie de Parkinson (106)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-17-item-106-maladie-de-parkinson\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 106, chapitre actuel</a></li><li><a href=\"https://www.cen-neurologie.fr/videotheque\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Vidéothèque de sémiologie neurologique</a></li></ul><p></p></details>","frequence":0}],"astuces":[{"type":"piege","titre":"Triade incomplète","contenu":"<div class=\"notion-course\"><p>Le tremblement est facultatif ; la <span class=\"nc-yellow_bg\">bradykinésie</span> est indispensable à la définition du syndrome.</p></div>"},{"type":"piege","titre":"Dégradation brutale","contenu":"<div class=\"notion-course\"><p>Rechercher d’abord une cause intercurrente ou médicamenteuse.</p></div>"},{"type":"piege","titre":"Lévodopa","contenu":"<div class=\"notion-course\"><p>Respecter les horaires et éviter tout arrêt brutal.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Syndrome parkinsonien, chronologie, <span class=\"nc-red nc-bold\">asymétrie</span>, médicaments et drapeaux rouges.</li><li>Pas d’examens systématiques dans une présentation typique.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li><span class=\"nc-green_bg\">Traitement</span> selon gêne et terrain ; dépistage des effets comportementaux.</li><li>Rééducation, activité physique et soutien dès le début.</li></ul></div>","Examens complémentaires":"<div class=\"notion-course\"><ul><li>IRM si atypie ; bilan Wilson si début jeune selon contexte.</li><li>DaTSCAN réservé à une question diagnostique précise.</li></ul></div>"},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d9418141a8b8f9a534437b3f?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-17-item-106-maladie-de-parkinson","label":"CEN · Item 106, chapitre actuel ↗"},{"href":"https://www.has-sante.fr/jcms/c_2038173/fr/maladie-de-parkinson-et-syndromes-apparentes-techniques-et-modalites-de-la-prise-en-charge-non-medicamenteuse-des-troubles-moteurs","label":"HAS · Parkinson : prise en charge non médicamenteuse des troubles moteurs ↗"},{"href":"https://ansm.sante.fr/actualites/la-domperidone-motilium-et-generiques-ne-doit-plus-etre-utilisee-chez-lenfant-de-moins-de-12-ans","label":"ANSM · Bon usage de la dompéridone ↗"},{"href":"https://www.cen-neurologie.fr/videotheque","label":"CEN · Vidéothèque de sémiologie neurologique ↗"},{"href":"https://livret.uness.fr/lisa/2026/Tremblements_SDD-128","label":"LiSA · SDD 128 — Tremblements ↗"},{"href":"https://livret.uness.fr/lisa/2026/Mouvements_anormaux_SDD-126","label":"LiSA · SDD 126 — Mouvements anormaux ↗"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Bradykinésie avec rigidité et/ou tremblement de repos ?","detail":"<ul><li>Mouvements répétés, tonus, repos et marche ; la triade complète n’est pas requise.</li></ul>","branches":[{"label":"Syndrome présent","to":"cause"},{"label":"Tremblement isolé / autre tableau","to":"autre"},{"label":"Examen incomplet","to":"doute"}]},{"id":"cause","kind":"decision","label":"Médicament ou signe atypique précoce ?","detail":"<ul><li>Revoir ordonnance ; chutes, regard vertical, cervelet, cognition et dysautonomie.</li></ul>","branches":[{"label":"Médicament plausible","to":"iatrogene"},{"label":"Signes atypiques / début jeune","to":"atypie"},{"label":"Présentation typique","to":"typique"}]},{"id":"iatrogene","kind":"finish","label":"Réviser le traitement avec le prescripteur","detail":"<ul><li>Diminuer/substituer si possible ; réévaluer après adaptation.</li><li>Persistance : rechercher maladie sous-jacente.</li></ul>","branches":[]},{"id":"atypie","kind":"finish","label":"Bilan spécialisé orienté","detail":"<ul><li>IRM et examens selon signes ; Wilson si début jeune évocateur.</li><li>DaTSCAN ne distingue pas à lui seul Parkinson, AMS et PSP.</li></ul>","branches":[]},{"id":"typique","kind":"finish","label":"Diagnostic clinique et prise en charge partagée","detail":"<ul><li>Pas d’examen systématique ; choisir traitement selon retentissement et terrain.</li><li>Rééducation, activité et dépistage non moteur.</li></ul>","branches":[]},{"id":"autre","kind":"finish","label":"Décrire le mouvement et compléter l’examen","detail":"<ul><li>Tremblement d’action, dystonie ou autre syndrome : parcours mouvements anormaux.</li></ul>","branches":[]},{"id":"doute","kind":"uncertain","label":"Vérifier les signes manquants","detail":"<ul><li>Ne pas diagnostiquer Parkinson sur un tremblement seul.</li></ul>","branches":[]}]},"cards":[{"i":"0b491c6feaaa","n":106,"o":"106-1","u":"Diagnostic positif","t":"Connaître les symptômes qui peuvent inaugurer une maladie de Parkinson","q":"Quels sont les principaux prodromes non moteurs pouvant inaugurer une maladie de Parkinson, plusieurs années avant les signes moteurs ?","a":"<div class=\"notion-course\"><p>Les prodromes non moteurs de la maladie de Parkinson incluent :</p><ul><li>Des troubles <strong>digestifs</strong> comme la <strong>constipation</strong>.</li><li>Des troubles de l'<strong>olfaction</strong>, notamment une <strong>hyposmie</strong> ou un <span class=\"nc-brown_bg\">déficit de l'odorat</span>.</li><li>Des troubles du <strong><span class=\"nc-green_bg\">sommeil</span></strong>, en particulier les <strong><span class=\"nc-brown_bg\">troubles du comportement en sommeil paradoxal</span> (RBD)</strong>, se manifestant par des rêves animés, des cauchemars, et des actes auto- ou hétéro-agressifs.</li><li>La <strong>douleur</strong>, telle qu'une douleur mécanique de l'épaule.</li></ul></div>"},{"i":"3160430aaae1","n":106,"o":"106-1","u":"Diagnostic positif","t":"Connaître les symptômes qui peuvent inaugurer une maladie de Parkinson","q":"La maladie de Parkinson peut-elle se présenter initialement avec des signes moteurs trompeurs en l'absence de tremblement de repos ? Si oui, lesquels ?","a":"<div class=\"notion-course\"><p>Oui : raideur ou douleur d’épaule, diminution de dextérité, <span class=\"nc-orange_bg\">ralentissement évoquant une dépression</span>. Le tremblement n’est pas obligatoire et peut rester absent.</p></div>"},{"i":"14a2d15cb702","n":106,"o":"106-11","u":"Prise en charge","t":"Connaître les médicaments susceptibles d’induire un syndrome parkinsonien","q":"Quelle est la physiopathologie principale du syndrome parkinsonien iatrogène ?","a":"<div class=\"notion-course\"><p>Souvent blocage dopaminergique D2 par un antipsychotique ou un antiémétique ; d’autres médicaments peuvent induire un parkinsonisme par d’autres mécanismes.</p></div>"},{"i":"1f52bf306489","n":106,"o":"106-11","u":"Prise en charge","t":"Connaître les médicaments susceptibles d’induire un syndrome parkinsonien","q":"Quels sont les médicaments les plus fréquemment mis en cause dans l'induction d'un syndrome parkinsonien iatrogène ?","a":"<div class=\"notion-course\"><ul><li>Antipsychotiques ; <span class=\"nc-pink_bg\">métoclopramide</span>, <span class=\"nc-pink_bg\">métopimazine</span> et autres antagonistes dopaminergiques.</li><li>Autres molécules possibles : flunarizine, trimétazidine, <span class=\"nc-pink_bg\">lithium</span>, <span class=\"nc-pink_bg\">valproate</span>… Toutes ne sont pas des « <span class=\"nc-pink_bg\">neuroleptiques</span> cachés ».</li></ul></div>"},{"i":"49439c6f6b05","n":106,"o":"106-11","u":"Prise en charge","t":"Connaître les médicaments susceptibles d’induire un syndrome parkinsonien","q":"Quelle est la première mesure à prendre face à un syndrome parkinsonien iatrogène ?","a":"<div class=\"notion-course\"><p>Réviser l’indication et la chronologie avec le prescripteur ; diminuer, arrêter ou substituer si possible. Ne pas interrompre seul un <span class=\"nc-green_bg\">traitement</span> indispensable.</p></div>"},{"i":"82125ef887c0","n":106,"o":"106-11","u":"Prise en charge","t":"Connaître les médicaments susceptibles d’induire un syndrome parkinsonien","q":"Quelles sont les caractéristiques cliniques qui orientent vers un syndrome parkinsonien iatrogène par rapport à une maladie de Parkinson typique ?","a":"<div class=\"notion-course\"><ul><li>Le syndrome est <span class=\"nc-yellow_bg\">plutôt </span><strong><span class=\"nc-yellow_bg\">symétrique</span></strong> (caractéristique inconstante).</li><li>Le <strong>tremblement</strong> est plus souvent <strong>postural ou d'action</strong> qu'un authentique tremblement de repos.</li><li>Des <strong><span class=\"nc-blue_bg\">dyskinésies bucco-linguo-faciales</span></strong> peuvent être associées.</li><li>Il y a une <strong><span class=\"nc-red nc-bold\">absence de réponse</span></strong><span class=\"nc-red nc-bold\"> au traitement dopaminergique</span>.</li></ul></div>"},{"i":"a6d11a1032eb","n":106,"o":"106-11","u":"Prise en charge","t":"Connaître les médicaments susceptibles d’induire un syndrome parkinsonien","q":"Si l'arrêt du neuroleptique inducteur d'un syndrome parkinsonien iatrogène n'est pas possible, quelles sont les alternatives thérapeutiques ?","a":"<div class=\"notion-course\"><ul><li>Substitution spécialisée selon indication : <span class=\"nc-pink_bg\">clozapine</span> ou <span class=\"nc-pink_bg\">quétiapine</span> possibles dans certaines situations ; surveillance propre au médicament.</li><li>Pas d’anticholinergique systématique, surtout chez le sujet âgé/cognitif. Réévaluer la réversibilité et une éventuelle maladie sous-jacente.</li></ul></div>"},{"i":"1e1aa035cae6","n":106,"o":"106-12","u":"Contenu multimédia","t":"Chez un patient réel ou sur un cas vidéo, définir les éléments qui orientent vers le diagnostic de maladie de Parkinson","q":"Quelle particularité de la présentation du syndrome parkinsonien est essentielle pour orienter vers le diagnostic de maladie de Parkinson ?","a":"<div class=\"notion-course\"><p>L'orientation diagnostique vers la maladie de Parkinson est fortement suggérée par une <strong><span class=\"nc-red nc-bold\">asymétrie</span> ou unilatéralité persistante</strong> du syndrome parkinsonien. Une présentation strictement <span class=\"nc-yellow_bg\">symétrique</span> doit faire évoquer d'autres diagnostics, comme une cause iatrogène ou vasculaire.</p></div>"},{"i":"6bd11f7e3833","n":106,"o":"106-12","u":"Contenu multimédia","t":"Chez un patient réel ou sur un cas vidéo, définir les éléments qui orientent vers le diagnostic de maladie de Parkinson","q":"Comment la marche et l'écriture peuvent-elles orienter vers le diagnostic de maladie de Parkinson ?","a":"<div class=\"notion-course\"><p>L'observation <span class=\"nc-yellow_bg\">de la</span> marche peut révéler des <strong>petits pas</strong> et une <strong><span class=\"nc-blue_bg\">perte du ballant du bras</span></strong> du côté le plus atteint. Concernant l'écriture, la <strong><span class=\"nc-blue_bg\">micrographie</span></strong> (réduction <span class=\"nc-red nc-bold\">progressive</span> <span class=\"nc-yellow_bg\">de la</span> taille des lettres) est un signe classique.</p></div>"},{"i":"81a2e0ef35df","n":106,"o":"106-12","u":"Contenu multimédia","t":"Chez un patient réel ou sur un cas vidéo, définir les éléments qui orientent vers le diagnostic de maladie de Parkinson","q":"Quels signes cliniques spécifiques doivent alerter et faire rechercher d'autres diagnostics que la maladie de Parkinson ?","a":"<div class=\"notion-course\"><p>Certains signes cliniques constituent des <strong>drapeaux rouges</strong>, orientant contre le diagnostic de maladie de Parkinson :</p><ul><li>Un syndrome <strong>strictement <span class=\"nc-yellow_bg\">symétrique</span></strong>.</li><li>Des <strong>mouvements oculaires anormaux</strong> (évoquant une <span class=\"nc-orange_bg\">paralysie supranucléaire progressive</span> - PSP).</li><li>Une <strong>dysarthrie <span class=\"nc-red_bg\">pseudo-bulbaire</span> <span class=\"nc-red nc-bold\">précoce</span></strong> (évoquant PSP, <span class=\"nc-orange_bg\">atrophie multisystématisée</span> - AMS).</li><li>Un <strong>tremblement d'action isolé</strong> ou un <strong>tremblement majoré à l'action</strong> (évoquant un <span class=\"nc-orange_bg\">tremblement essentiel</span>).</li><li>Une <strong>maladresse cérébelleuse</strong> (dysmétrie au doigt-nez), une <strong>ataxie cérébelleuse</strong>.</li><li>Des <strong><span class=\"nc-red nc-bold\">chutes précoces</span></strong> ou une altération <span class=\"nc-red nc-bold\">précoce</span> des réflexes posturaux (évoquant PSP, AMS).</li><li>Toute <strong>anomalie neurologique associée</strong> (cérébelleuse, pyramidale, corticale, oculomotrice) en dehors du syndrome parkinsonien lui-même.</li></ul></div>"},{"i":"b058e3d95544","n":106,"o":"106-12","u":"Contenu multimédia","t":"Chez un patient réel ou sur un cas vidéo, définir les éléments qui orientent vers le diagnostic de maladie de Parkinson","q":"Quels sont les trois éléments clés de la triade clinique qui orientent vers le diagnostic de maladie de Parkinson ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-yellow_bg\">Bradykinésie</span>, rigidité plastique et tremblement de repos constituent la triade classique.</li><li>Pour définir un syndrome parkinsonien : <span class=\"nc-yellow_bg\">bradykinésie</span> + rigidité et/ou tremblement ; les trois ne sont pas exigés.</li></ul></div>"},{"i":"1385fa14f4c2","n":106,"o":"106-2","u":"Diagnostic positif","t":"Décrire les signes cliniques d’une maladie de Parkinson","q":"Comment caractérise-t-on la rigidité plastique retrouvée dans la maladie de Parkinson ?","a":"<div class=\"notion-course\"><p>La rigidité plastique est une résistance constante au <span class=\"nc-green_bg\">mouvement</span> passif, décrite <strong>« en tuyau de plomb »</strong>. Elle se différencie de la rigidité spastique par sa topographie (plus aux <span class=\"nc-blue_bg\">extrémités</span> et à la <span class=\"nc-blue_bg\">nuque</span>) et sa modalité : lors de la mobilisation passive, elle <span class=\"nc-blue_bg\">cède par </span><strong><span class=\"nc-blue_bg\">à-coups en « roue dentée »</span></strong>. Elle peut être majorée par la <strong>manœuvre de Froment</strong> (mouvements passifs d'une main associés à une tâche volontaire de l'autre main).</p></div>"},{"i":"2f35b26d61b7","n":106,"o":"106-2","u":"Diagnostic positif","t":"Décrire les signes cliniques d’une maladie de Parkinson","q":"Comment définit-on cliniquement le syndrome parkinsonien dans le cadre de la maladie de Parkinson ?","a":"<div class=\"notion-course\"><p>Le syndrome parkinsonien est défini par l'association obligatoire d'une <strong><span class=\"nc-yellow_bg\">bradykinésie</span></strong>, à laquelle s'ajoutent une <strong>rigidité plastique</strong> et/ou un <strong>tremblement de repos</strong>. Une caractéristique cardinale est son <strong>début <span class=\"nc-red nc-bold\">unilatéral</span> ou <span class=\"nc-red nc-bold\">asymétrique</span></strong>, cette <span class=\"nc-red nc-bold\">asymétrie</span> persistant tout au long de la maladie.</p></div>"},{"i":"7bdbba41809b","n":106,"o":"106-2","u":"Diagnostic positif","t":"Décrire les signes cliniques d’une maladie de Parkinson","q":"Quelles sont les caractéristiques cliniques de la bradykinésie dans la maladie de Parkinson ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-yellow_bg\">bradykinésie</span> se manifeste par :</p><ul><li>Des <strong>mouvements lents</strong> (ralentissement à l'exécution, décrément de vitesse).</li><li>Une <strong><span class=\"nc-yellow_bg\">hypokinésie</span></strong> (mouvements moins amples) et/ou une <strong><span class=\"nc-yellow_bg\">akinésie</span></strong> (défaut d'initiation).</li><li><strong><span class=\"nc-blue_bg\">Micrographie</span></strong> (réduction de la taille des lettres à l'écriture).</li><li><strong><span class=\"nc-blue_bg\">Voix monocorde et monotone</span></strong>.</li><li>Marche lente, à <strong>petits pas</strong>, avec <strong><span class=\"nc-blue_bg\">perte du ballant du bras</span></strong>.</li><li><strong><span class=\"nc-blue_bg\">Hypomimie</span> faciale</strong>, <span class=\"nc-blue_bg\">pauvreté des mouvements spontanés</span> (clignement des yeux).</li><li><span class=\"nc-blue_bg\">Ralentissement des gestes alternatifs rapides</span> (ex: <span class=\"nc-red nc-bold\">opposition pouce-index</span>, <span class=\"nc-red nc-bold\">battre à mesure avec le pied</span>).</li></ul></div>"},{"i":"ec17461cecb9","n":106,"o":"106-2","u":"Diagnostic positif","t":"Décrire les signes cliniques d’une maladie de Parkinson","q":"Quelles sont les principales caractéristiques du tremblement de repos dans la maladie de Parkinson ?","a":"<div class=\"notion-course\"><p>Le tremblement de repos est un tremblement <strong><span class=\"nc-pink nc-bold\">lent</span></strong> (<strong>4-6 Hz</strong>), <strong><span class=\"nc-red nc-bold\">unilatéral</span> ou <span class=\"nc-red nc-bold\">asymétrique</span></strong>, qui <strong>disparaît au <span class=\"nc-green_bg\">mouvement</span> volontaire et pendant le <span class=\"nc-green_bg\">sommeil</span></strong>. Il touche principalement les <strong><span class=\"nc-blue_bg\">membres en distalité</span></strong>, les <span class=\"nc-blue_bg\">lèvres</span>, le <span class=\"nc-blue_bg\">menton</span> et la <span class=\"nc-blue_bg\">langue</span>, mais <strong>jamais le chef <span class=\"nc-red_bg\">(la tête)</span></strong>. Il peut être <strong>aggravé par l'<span class=\"nc-red nc-bold\">émotion</span> ou le <span class=\"nc-red nc-bold\">calcul mental</span></strong>.</p></div>"},{"i":"049f1f1f70df","n":106,"o":"106-4","u":"Diagnostic positif","t":"Connaître les signes cliniques dont l’association à un syndrome parkinsonien va à l’encontre du diagnostic de maladie de Parkinson","q":"Quelles associations cliniques à un syndrome parkinsonien évoquent une dégénérescence cortico-basale ou une démence à corps de Lewy plutôt qu'une maladie de Parkinson ?","a":"<div class=\"notion-course\"><p>Des <strong>signes corticaux</strong> (<span class=\"nc-red_bg\">aphasie</span>, <span class=\"nc-red_bg\">apraxie</span>, <span class=\"nc-red_bg\">myoclonies</span>, <span class=\"nc-red_bg\">astéréognosie</span>) orientent vers une <span class=\"nc-orange_bg\">dégénérescence cortico-basale</span>. Une <strong>atteinte <span class=\"nc-red_bg\">cognitive</span> <span class=\"nc-red nc-bold\">précoce</span></strong> (contemporaine ou précédant le syndrome parkinsonien) suggère une <span class=\"nc-orange_bg\">démence à corps de Lewy</span>.</p></div>"},{"i":"2974788721a3","n":106,"o":"106-4","u":"Diagnostic positif","t":"Connaître les signes cliniques dont l’association à un syndrome parkinsonien va à l’encontre du diagnostic de maladie de Parkinson","q":"Quelle est la règle générale concernant l'examen neurologique pour le diagnostic de la maladie de Parkinson ?","a":"<div class=\"notion-course\"><p>Rechercher des signes atypiques précoces : <span class=\"nc-purple nc-bold\">cérébelleux</span>, pyramidal, oculomoteur, cortical, <span class=\"nc-orange nc-bold\">dysautonomie</span> sévère ou chutes. Des <span class=\"nc-blue_bg\">signes non moteurs</span> peuvent appartenir à Parkinson ; l’examen n’est pas nécessairement normal hors syndrome parkinsonien à tous les stades.</p></div>"},{"i":"cd0af5c6b782","n":106,"o":"106-4","u":"Diagnostic positif","t":"Connaître les signes cliniques dont l’association à un syndrome parkinsonien va à l’encontre du diagnostic de maladie de Parkinson","q":"Quelle association clinique va à l'encontre du diagnostic de maladie de Parkinson et doit faire évoquer une atrophie multisystématisée (AMS) ?","a":"<div class=\"notion-course\"><p>Devant un syndrome parkinsonien, l'association à un <strong><span class=\"nc-red_bg\">syndrome cérébelleux</span></strong>, une <strong><span class=\"nc-red_bg\">atteinte pyramidale</span></strong> ou une <strong><span class=\"nc-orange nc-bold\">dysautonomie</span> <span class=\"nc-red nc-bold\">précoce</span> et sévère</strong> (hypotension orthostatique (<span class=\"nc-blue nc-bold\">HTO</span>) sévère ou incontinence urinaire) doit faire évoquer une <span class=\"nc-orange_bg\">atrophie multisystématisée</span>.</p></div>"},{"i":"e3c781028dbb","n":106,"o":"106-4","u":"Diagnostic positif","t":"Connaître les signes cliniques dont l’association à un syndrome parkinsonien va à l’encontre du diagnostic de maladie de Parkinson","q":"Quelles associations cliniques à un syndrome parkinsonien sont des \"drapeaux rouges\" pour le diagnostic de maladie de Parkinson et orientent vers une paralysie supra-nucléaire progressive (PSP) ?","a":"<div class=\"notion-course\"><p>Les signes qui orientent vers une paralysie supra-nucléaire <span class=\"nc-red nc-bold\">progressive</span> (maladie de Steele-Richardson) en association avec un syndrome parkinsonien sont des <strong><span class=\"nc-red_bg\">troubles oculomoteurs</span></strong>, une <strong>progression rapide avec <span class=\"nc-red nc-bold\">chutes précoces</span></strong>, ou des <strong>signes pseudo-bulbaires précoces</strong> (tels que la <span class=\"nc-blue_bg\">dysarthrie</span> et la <span class=\"nc-blue_bg\">dysphagie</span>).</p></div>"},{"i":"630e3d9da515","n":106,"o":"106-3","u":"Eléments physiopathologiques","t":"Connaître le processus physiopathologique de la maladie de Parkinson","q":"Quels éléments forment le noyau lenticulaire ?","a":"<div class=\"notion-course\"><ul><li>Putamen + pallidum. Le striatum comprend noyau caudé + putamen.</li></ul></div>"},{"i":"ae36d3a17e55","n":106,"o":"106-5","u":"Diagnostic positif","t":"Connaître les manifestations de la phase des complications motrices","q":"Comment différencier wearing-off et dyskinésie de pic de dose ?","a":"<div class=\"notion-course\"><ul><li>Wearing-off : réapparition des symptômes avant la prise suivante. <span class=\"nc-red nc-bold\">Pic</span> de dose : mouvements involontaires souvent <span class=\"nc-blue_bg\">choréiques</span> au maximum d’effet. L’ajustement thérapeutique diffère.</li></ul></div>"},{"i":"80e587a081c1","n":106,"o":"106-6","u":"Diagnostic positif","t":"Enoncer les manifestations de la phase de déclin moteur","q":"Quels signes caractérisent le déclin axial de Parkinson ?","a":"<div class=\"notion-course\"><ul><li>Freezing, instabilité posturale, troubles de posture, <span class=\"nc-blue_bg\">dysarthrie</span> et <span class=\"nc-blue_bg\">dysphagie</span> ; souvent moins dopasensibles. Prévenir chutes et inhalation.</li></ul></div>"},{"i":"c737c7977575","n":106,"o":"106-7","u":"Diagnostic positif","t":"Connaître les manifestations de la phase de déclin cognitif et comportemental","q":"Que rechercher devant des hallucinations d’installation aiguë chez un patient parkinsonien ?","a":"<div class=\"notion-course\"><ul><li>Une confusion : infection, douleur, rétention, déshydratation, trouble métabolique ou médicament. Réviser le <span class=\"nc-green_bg\">traitement</span> avec le spécialiste, sans arrêt brutal de lévodopa.</li></ul></div>"},{"i":"8737c90b2990","n":106,"o":"106-8","u":"Prise en charge","t":"Connaître les différentes classes de médicaments antiparkinsoniens","q":"Quels effets indésirables faut-il expliquer avant un agoniste dopaminergique ?","a":"<div class=\"notion-course\"><ul><li>Troubles des impulsions, somnolence/attaques d’endormissement, <span class=\"nc-red_bg\">hallucinations</span>, hypotension, <span class=\"nc-blue_bg\">nausées</span> et œdèmes. Interroger également les proches.</li></ul></div>"},{"i":"48ffd63d8552","n":106,"o":"106-9","u":"Prise en charge","t":"Connaître les thérapeutiques non médicamenteuses et l’importance de la kinésithérapie","q":"Faut-il imposer la kinésithérapie avant la première prise de lévodopa ?","a":"<div class=\"notion-course\"><ul><li>Non. Adapter horaires, intensité et exercices à l’état moteur et à la sécurité, souvent en période ON ; pas d’épuisement recherché systématiquement.</li></ul></div>"},{"i":"0f1106ff5073","n":106,"o":"106-10","u":"Prise en charge","t":"Connaître les principes du traitement à la phase initiale de la maladie","q":"Peut-on débuter la lévodopa chez un patient jeune avec handicap moteur gênant ?","a":"<div class=\"notion-course\"><ul><li>Oui. Le choix tient compte du retentissement et des risques ; ne pas retarder un <span class=\"nc-green_bg\">traitement</span> efficace uniquement pour repousser des complications futures.</li></ul></div>"},{"i":"5277c68fc702","n":106,"o":"106-4","u":"Diagnostic positif","t":"Connaître les signes cliniques dont l’association à un syndrome parkinsonien va à l’encontre du diagnostic de maladie de Parkinson","q":"Un DaTSCAN anormal distingue-t-il Parkinson d’une AMS ou d’une PSP ?","a":"<div class=\"notion-course\"><ul><li>Non. Il montre une dénervation dopaminergique présynaptique ; le diagnostic entre syndromes dégénératifs reste clinique et spécialisé.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d9418141a8b8f9a534437b3f?pvs=204","reviewedAt":"2026-10-13","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif.","sddVerifiedAt":"2026-10-13","sdd":[{"number":128,"title":"Tremblements","url":"https://livret.uness.fr/lisa/2026/Tremblements_SDD-128"},{"number":126,"title":"Mouvements anormaux","url":"https://livret.uness.fr/lisa/2026/Mouvements_anormaux_SDD-126"}]}};
